/**
 * OMEGA COMPUTER - Virtual CPU Simulator
 * ISA: MOV, LOAD, STORE, ADD, SUB, MUL, DIV, CMP, JMP, JE, JNE, CALL, RET, PUSH, POP, AND, OR, XOR, NOT, HALT
 */
export interface Registers {
  A: number;
  B: number;
  C: number;
  D: number;
  PC: number;
  SP: number;
  FLAGS: { zero: number; negative: number; carry: number };
}

export class VirtualCPU {
  public registers: Registers = {
    A: 0,
    B: 0,
    C: 0,
    D: 0,
    PC: 0,
    SP: 1023,
    FLAGS: { zero: 0, negative: 0, carry: 0 }
  };
  public halted: boolean = false;
  public memory: Uint8Array = new Uint8Array(1024);

  constructor() {
    this.reset();
  }

  public reset(): void {
    this.registers = {
      A: 0,
      B: 0,
      C: 0,
      D: 0,
      PC: 0,
      SP: 1023,
      FLAGS: { zero: 0, negative: 0, carry: 0 }
    };
    this.halted = false;
    this.memory.fill(0);
  }

  public step(): void {
    if (this.halted) return;
    // Simple fetch-decode-execute stub
    const opcode = this.memory[this.registers.PC];
    if (opcode === 0xFF) {
      this.halted = true;
    } else {
      this.registers.PC++;
    }
  }

  public getState() {
    return { registers: { ...this.registers }, halted: this.halted };
  }
}

/**
 * OMEGA-LANG Compiler & Interpreter Pipeline
 */
export class OmegaLangCompiler {
  public compile(source: string): string[] {
    const lines = source.split('\n');
    const bytecode: string[] = [];
    for (const line of lines) {
      const trimmed = line.trim();
      if (trimmed.startsWith('let ')) {
        bytecode.push(`MOV ${trimmed.replace('let ', '')}`);
      } else if (trimmed.startsWith('print(')) {
        bytecode.push(`OUT ${trimmed.substring(6, trimmed.length - 1)}`);
      }
    }
    bytecode.push('HALT');
    return bytecode;
  }
}
